  IEnumerator FailedSceneRecovery(){var original=session.catalog;var clone=Object.Instantiate(original);var e=original.entries[0];var bad=new WarSandboxBattlefieldEntry{contentVersion=e.contentVersion,terrainId=e.terrainId,terrainVersion=e.terrainVersion,terrainSurface=e.terrainSurface,rules=e.rules};bad.id="p9-no-manager-fixture";bad.displayName="P9 owned failed scene";bad.scenePath="Assets/Game/Scenes/MainMenu.unity";clone.entries=original.entries.Concat(new[]{bad}).ToArray();session.catalog=clone;Assert.True(session.TryEnterBattlefield(bad.id,false,out var error),error);double until=Time.realtimeSinceStartupAsDouble+120;while(session.IsLoading&&Time.realtimeSinceStartupAsDouble<until)yield return null;Assert.False(session.IsLoading);Assert.AreEqual(WarSandboxEntryState.Failed,session.State);Assert.IsNotEmpty(session.Error);Assert.IsNull(session.Controller);yield return Frames();yield return Click("failure-return");yield return Loaded();Assert.AreEqual(WarSandboxEntryState.Menu,session.State);session.catalog=original;Object.Destroy(clone);yield return Enter("forest-green22");yield return Menu();Mark("scene-failure-ui-recovered","in-memory catalog points to no-manager scene; actual Failed screen return callback; successful official reload; no asset edits");}
  IEnumerator FixedGameView(){var asm=typeof(EditorWindow).Assembly;var sizesType=asm.GetType("UnityEditor.GameViewSizes");var singleton=typeof(ScriptableSingleton<>).MakeGenericType(sizesType);var sizes=singleton.GetProperty("instance",BindingFlags.Public|BindingFlags.Static).GetValue(null);var groupType=asm.GetType("UnityEditor.GameViewSizeGroupType");var group=sizesType.GetMethod("GetGroup").Invoke(sizes,new[]{Enum.Parse(groupType,"Standalone")});var gt=group.GetType();int index=(int)gt.GetMethod("GetBuiltinCount").Invoke(group,null)+(int)gt.GetMethod("GetCustomCount").Invoke(group,null);var sizeType=asm.GetType("UnityEditor.GameViewSize");var modeType=asm.GetType("UnityEditor.GameViewSizeType");var size=Activator.CreateInstance(sizeType,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{Enum.Parse(modeType,"FixedResolution"),1280,720,"P9 owned 1280x720"},CultureInfo.InvariantCulture);gt.GetMethod("AddCustomSize").Invoke(group,new[]{size});var view=EditorWindow.GetWindow(asm.GetType("UnityEditor.GameView"));view.Show();view.Focus();view.GetType().GetProperty("selectedSizeIndex",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).SetValue(view,index);yield return Frames(30);Assert.AreEqual(1280,Screen.width);Assert.AreEqual(720,Screen.height);Mark("fixed-render-size","1280x720; owned Editor preferences journaled by runner");}
  IEnumerator BackendReady(){double until=Time.realtimeSinceStartupAsDouble+75;while(TerrainNavigationRuntime.BurstReserveRequested&&Runtime.PreparationState=="Waiting"&&Time.realtimeSinceStartupAsDouble<until)yield return null;if(TerrainNavigationRuntime.BurstReserveRequested)Assert.AreEqual("Ready",Runtime.PreparationState,Runtime.PreparationBlockReason);else{Assert.AreEqual(0,Runtime.BurstSolveCount);Assert.AreEqual(0,WorkspaceCount());}}
  IEnumerator Sample(int repeat){var cam=m.cullingCamera;Assert.NotNull(cam);cam.transform.position=new Vector3(0,180,-120);cam.transform.LookAt(Vector3.zero);Vector3 p=cam.transform.position;Quaternion rotation=cam.transform.rotation;yield return Frames(90);yield return BackendReady();var rows=new List<string>{"frame,wall_ms,unity_allocated_bytes,unity_reserved_bytes,selection_bytes,local_bytes,readback_pairs,snapshot_requests,ack_requests,burst_solves,managed_solves"};double previous=Time.realtimeSinceStartupAsDouble;for(int i=0;i<300;i++){cam.transform.SetPositionAndRotation(p,rotation);yield return null;double now=Time.realtimeSinceStartupAsDouble;rows.Add(string.Join(",",i,F((now-previous)*1000),UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),UnityEngine.Profiling.Profiler.GetTotalReservedMemoryLong(),hud.SelectionPreview?.LogicalGpuBytes??0,m.LocalOrders?.GpuBytes??0,hud.SelectionPreview?.ReadbackPairs??0,m.LocalOrders?.SnapshotRequests??0,m.LocalOrders?.AckRequests??0,Runtime.BurstSolveCount,Runtime.ManagedSolveCount));previous=now;}File.WriteAllLines(Path.Combine(output,"repeat-"+repeat+"-frames.csv"),rows);Assert.AreEqual(2048,m.Buffers.AgentCount);if(TerrainNavigationRuntime.BurstReserveRequested)Assert.Greater(Runtime.BurstSolveCount,0,"Opt-in must actually execute native solves");else Assert.AreEqual(0,Runtime.BurstSolveCount);Mark("repeat-sampled",repeat+";300 wall-frame samples;fixed camera/settings;Editor not Player FPS qualification");}
  [UnityTest,Timeout(900000)]public IEnumerator P9Repeated2048ScopedFeedbackAndResourceRelease(){
   Assert.False(Application.isBatchMode,"Run performance in an owned rendered Editor, not batch/nographics");var gameView=EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView"));gameView.Show();gameView.Focus();yield return FixedGameView();var resources=new List<string>{"repeat,unity_allocated_after_unload,unity_reserved_after_unload,textures,rendertextures,materials,gameobjects,active_native_workspaces"};
   for(int run=1;run<=3;run++){yield return Enter();Assert.True(c.IssueOrder(ArmyOrder.Hold(0)));Assert.True(c.IssueOrder(ArmyOrder.Hold(1)));yield return Frames(90);yield return BackendReady();Assert.True(c.StartDefaultBattle());yield return Frames(60);Assert.True(c.IssueOrder(ArmyOrder.Hold(0)));Assert.True(c.IssueOrder(ArmyOrder.Hold(1)));yield return Frames();Mark("whole-navigation-warmup","repeat="+run+";burst="+Runtime.BurstSolveCount+";managed="+Runtime.ManagedSolveCount);yield return Four("repeat-"+run);yield return Sample(run);yield return Menu();resources.Add(string.Join(",",run,UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),UnityEngine.Profiling.Profiler.GetTotalReservedMemoryLong(),Resources.FindObjectsOfTypeAll<Texture>().Length,Resources.FindObjectsOfTypeAll<RenderTexture>().Length,Resources.FindObjectsOfTypeAll<Material>().Length,Resources.FindObjectsOfTypeAll<GameObject>().Length,WorkspaceCount()));File.WriteAllLines(Path.Combine(output,"repeat-resources.csv"),resources);}
   Mark("repeated-2048-complete","3 cycles;buffer/native ownership gates passed;frame/memory trends require report analysis, not automatic 30FPS claim");
  }
